package cmd

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"

	"xq/internal/contenttype"
	"xq/internal/formatter"
)

const version = "1.4.0"

type Options struct {
	Color      bool
	NoColor    bool
	Tab        bool
	Indent     int
	XPath      string
	Extract    string
	Query      string
	Attr       string
	Html       bool
	Json       bool
	Node       bool
	InPlace    bool
	Compact    bool
	Depth      int
	Help       bool
	Version    bool
}

// flag spec used both for parsing and for help rendering
type flagSpec struct {
	short      string // e.g. "a" (empty if no short)
	long       string // e.g. "attr"
	argType    string // "", "string", "int"
	defaultVal string // only used for display when needed
	helpText   string
}

var flagSpecs = []flagSpec{
	{"a", "attr", "string", "", "Extract an attribute value instead of node content for provided CSS query"},
	{"c", "color", "", "", "Force colorful output"},
	{"", "compact", "", "", "Compact JSON output (no indentation)"},
	{"d", "depth", "int", "-1", "Maximum nesting depth for JSON output (-1 for unlimited) (default -1)"},
	{"e", "extract", "string", "", "Extract a single node from XML"},
	{"h", "help", "", "", "Print this help message"},
	{"m", "html", "", "", "Use HTML formatter"},
	{"i", "in-place", "", "", "Format file in place"},
	{"", "indent", "int", "2", "Use the given number of spaces for indentation (default 2)"},
	{"j", "json", "", "", "Output the result as JSON"},
	{"", "no-color", "", "", "Disable colorful output"},
	{"n", "node", "", "", "Return the node content instead of text"},
	{"q", "query", "string", "", "Extract the node(s) using CSS selector"},
	{"", "tab", "", "", "Use tabs for indentation"},
	{"v", "version", "", "", "Print version information"},
	{"x", "xpath", "string", "", "Extract the node(s) from XML"},
}

func printHelp(out io.Writer) {
	fmt.Fprintln(out, "Command-line XML and HTML beautifier and content extractor")
	fmt.Fprintln(out, "")
	fmt.Fprintln(out, "Usage:")
	fmt.Fprintln(out, "  xq [flags]")
	fmt.Fprintln(out, "")
	fmt.Fprintln(out, "Flags:")
	// Compute alignment like cobra: "  -x, --long type   " with padding to longest
	type line struct {
		prefix string
		help   string
	}
	var lines []line
	maxPrefix := 0
	for _, fs := range flagSpecs {
		var b strings.Builder
		b.WriteString("  ")
		if fs.short != "" {
			b.WriteString("-")
			b.WriteString(fs.short)
			b.WriteString(", --")
		} else {
			b.WriteString("    --")
		}
		b.WriteString(fs.long)
		if fs.argType != "" {
			b.WriteString(" ")
			b.WriteString(fs.argType)
		}
		prefix := b.String()
		if len(prefix) > maxPrefix {
			maxPrefix = len(prefix)
		}
		lines = append(lines, line{prefix: prefix, help: fs.helpText})
	}
	for _, l := range lines {
		pad := strings.Repeat(" ", maxPrefix-len(l.prefix)+3)
		fmt.Fprintf(out, "%s%s%s\n", l.prefix, pad, l.help)
	}
}

func Execute() error {
	args := os.Args[1:]
	opts := Options{
		Indent: 2,
		Depth:  -1,
	}
	var positional []string

	i := 0
	for i < len(args) {
		a := args[i]
		if a == "--" {
			positional = append(positional, args[i+1:]...)
			break
		}
		if strings.HasPrefix(a, "--") {
			// long form; may contain =
			name := a[2:]
			value := ""
			hasValue := false
			if idx := strings.Index(name, "="); idx >= 0 {
				value = name[idx+1:]
				name = name[:idx]
				hasValue = true
			}
			fs := findLong(name)
			if fs == nil {
				return fmt.Errorf("unknown flag: --%s", name)
			}
			if fs.argType != "" {
				if !hasValue {
					if i+1 >= len(args) {
						return fmt.Errorf("flag needs an argument: --%s", name)
					}
					i++
					value = args[i]
				}
				if err := setOpt(&opts, fs.long, value); err != nil {
					return err
				}
			} else {
				if hasValue {
					if err := setOpt(&opts, fs.long, value); err != nil {
						return err
					}
				} else {
					if err := setOpt(&opts, fs.long, "true"); err != nil {
						return err
					}
				}
			}
			i++
			continue
		}
		if strings.HasPrefix(a, "-") && len(a) > 1 {
			// short form; may be combined: -abc
			rest := a[1:]
			for len(rest) > 0 {
				sh := string(rest[0])
				fs := findShort(sh)
				if fs == nil {
					return fmt.Errorf("unknown shorthand flag: '%s' in -%s", sh, a[1:])
				}
				rest = rest[1:]
				if fs.argType != "" {
					var value string
					if len(rest) > 0 {
						value = rest
						rest = ""
					} else {
						if i+1 >= len(args) {
							return fmt.Errorf("flag needs an argument: '%s' in -%s", sh, a[1:])
						}
						i++
						value = args[i]
					}
					if err := setOpt(&opts, fs.long, value); err != nil {
						return err
					}
				} else {
					if err := setOpt(&opts, fs.long, "true"); err != nil {
						return err
					}
				}
			}
			i++
			continue
		}
		positional = append(positional, a)
		i++
	}

	if opts.Help {
		printHelp(os.Stdout)
		return nil
	}
	if opts.Version {
		fmt.Printf("xq version %s\n", version)
		return nil
	}

	// Determine input
	var reader io.Reader
	var filePath string
	if len(positional) > 0 {
		if len(positional) > 1 {
			return errors.New("only one file path is supported")
		}
		filePath = positional[0]
		f, err := os.Open(filePath)
		if err != nil {
			return err
		}
		defer f.Close()
		reader = f
	} else {
		// stdin
		st, err := os.Stdin.Stat()
		if err == nil {
			// If stdin is a char device (terminal or /dev/null), show help and return
			if st.Mode()&os.ModeCharDevice != 0 {
				printHelp(os.Stdout)
				return nil
			}
		}
		reader = os.Stdin
	}

	if opts.InPlace {
		if filePath == "" {
			return errors.New("in-place formatting requires a file path (and only one file path)")
		}
	}

	// Read entire content
	data, err := io.ReadAll(reader)
	if err != nil {
		return err
	}

	out := io.Writer(os.Stdout)
	var outputBuf *bytes.Buffer
	if opts.InPlace {
		outputBuf = &bytes.Buffer{}
		out = outputBuf
	}

	colorful := shouldUseColor(opts, out)

	indent := "  "
	if opts.Tab {
		indent = "\t"
	} else if opts.Indent > 0 {
		indent = strings.Repeat(" ", opts.Indent)
	}

	formatOpts := formatter.Options{
		Indent:    indent,
		Color:     colorful,
		HTML:      opts.Html,
		JSONOut:   opts.Json,
		Node:      opts.Node,
		Compact:   opts.Compact,
		Depth:     opts.Depth,
		XPath:     opts.XPath,
		Extract:   opts.Extract,
		Query:     opts.Query,
		Attr:      opts.Attr,
	}

	ct := contenttype.Detect(data, opts.Html, opts.Json)

	switch ct {
	case contenttype.XML, contenttype.HTML:
		if opts.XPath != "" || opts.Extract != "" {
			return formatter.QueryXPath(data, out, formatOpts)
		}
		if opts.Query != "" {
			return formatter.QueryCSS(data, out, formatOpts)
		}
		if opts.Json {
			return formatter.XMLToJSON(data, out, formatOpts)
		}
		if opts.Html || ct == contenttype.HTML {
			if err := formatter.FormatHTML(data, out, formatOpts); err != nil {
				return err
			}
		} else {
			if err := formatter.FormatXML(data, out, formatOpts); err != nil {
				return err
			}
		}
	case contenttype.JSON:
		if err := formatter.FormatJSON(data, out, formatOpts); err != nil {
			return err
		}
	case contenttype.Text:
		out.Write(data)
		if len(data) == 0 || data[len(data)-1] != '\n' {
			io.WriteString(out, "\n")
		}
	case contenttype.Unknown:
		return fmt.Errorf("unknown content type: %d", 3)
	}

	if opts.InPlace && filePath != "" {
		return os.WriteFile(filePath, outputBuf.Bytes(), 0644)
	}
	return nil
}

func shouldUseColor(opts Options, w io.Writer) bool {
	if opts.NoColor {
		return false
	}
	if opts.Color {
		return true
	}
	// Default: colorful if output is terminal
	if f, ok := w.(*os.File); ok {
		st, err := f.Stat()
		if err == nil && (st.Mode()&os.ModeCharDevice) != 0 {
			return true
		}
	}
	return false
}

func findLong(name string) *flagSpec {
	for i := range flagSpecs {
		if flagSpecs[i].long == name {
			return &flagSpecs[i]
		}
	}
	return nil
}

func findShort(short string) *flagSpec {
	for i := range flagSpecs {
		if flagSpecs[i].short == short {
			return &flagSpecs[i]
		}
	}
	return nil
}

func setOpt(o *Options, name, value string) error {
	switch name {
	case "attr":
		o.Attr = value
	case "color":
		o.Color = parseBool(value)
	case "compact":
		o.Compact = parseBool(value)
	case "depth":
		n, err := strconv.ParseInt(value, 10, 64)
		if err != nil {
			return fmt.Errorf("invalid argument %q for \"--%s\" flag: %s", value, name, err.Error())
		}
		o.Depth = int(n)
	case "extract":
		o.Extract = value
	case "help":
		o.Help = parseBool(value)
	case "html":
		o.Html = parseBool(value)
	case "in-place":
		o.InPlace = parseBool(value)
	case "indent":
		n, err := strconv.ParseInt(value, 10, 64)
		if err != nil {
			return fmt.Errorf("invalid argument %q for \"--%s\" flag: %s", value, name, err.Error())
		}
		o.Indent = int(n)
	case "json":
		o.Json = parseBool(value)
	case "no-color":
		o.NoColor = parseBool(value)
	case "node":
		o.Node = parseBool(value)
	case "query":
		o.Query = value
	case "tab":
		o.Tab = parseBool(value)
	case "version":
		o.Version = parseBool(value)
	case "xpath":
		o.XPath = value
	default:
		return fmt.Errorf("unknown flag: --%s", name)
	}
	return nil
}

func parseBool(s string) bool {
	return s == "true" || s == "1" || s == ""
}
