package xmlparse

import (
	"fmt"
	"strings"
)

type TokenKind int

const (
	TokenStart TokenKind = iota
	TokenEnd
	TokenSelfClose
	TokenText
	TokenComment
	TokenCData
	TokenProcInst
	TokenDoctype
	TokenDecl // XML declaration <?xml ...?>
)

type Attribute struct {
	// Raw contains the original slice of text between tag name and the closing > / />
	// We instead parse into Name, Equals, Value with raw preservation.
	Raw string // original raw segment (for spacing preservation)
}

type Token struct {
	Kind    TokenKind
	Name    string // tag name for Start/End/SelfClose
	Attrs   string // raw attribute string, starting with a space (preserved verbatim)
	Text    string // text for Text/Comment/CData (content)
	Raw     string // full raw token text as it appears in source
}

type Tokenizer struct {
	src    []byte
	pos    int
	line   int
}

func New(src []byte) *Tokenizer {
	return &Tokenizer{src: src, line: 1}
}

// Err describes a syntax error.
type Err struct {
	Line int
	Msg  string
}

func (e *Err) Error() string {
	return fmt.Sprintf("XML syntax error on line %d: %s", e.Line, e.Msg)
}

func (t *Tokenizer) errorf(format string, args ...interface{}) error {
	return &Err{Line: t.line, Msg: fmt.Sprintf(format, args...)}
}

func (t *Tokenizer) countLines(s string) {
	for _, c := range s {
		if c == '\n' {
			t.line++
		}
	}
}

// Next returns the next token. Returns nil, io.EOF at end.
// Returns an error on malformed XML.
func (t *Tokenizer) Next() (*Token, error) {
	if t.pos >= len(t.src) {
		return nil, nil
	}
	// Text run until next '<'
	if t.src[t.pos] != '<' {
		start := t.pos
		for t.pos < len(t.src) && t.src[t.pos] != '<' {
			t.pos++
		}
		text := string(t.src[start:t.pos])
		t.countLines(text)
		return &Token{Kind: TokenText, Text: text, Raw: text}, nil
	}
	// Starts with '<'
	// Check various forms
	rest := t.src[t.pos:]
	// Comment
	if len(rest) >= 4 && string(rest[:4]) == "<!--" {
		end := indexOfBytes(rest, []byte("-->"))
		if end < 0 {
			return nil, t.errorf("unexpected EOF in comment")
		}
		raw := string(rest[:end+3])
		content := string(rest[4:end])
		t.pos += end + 3
		t.countLines(raw)
		return &Token{Kind: TokenComment, Text: content, Raw: raw}, nil
	}
	// CDATA
	if len(rest) >= 9 && string(rest[:9]) == "<![CDATA[" {
		end := indexOfBytes(rest, []byte("]]>"))
		if end < 0 {
			return nil, t.errorf("unexpected EOF in CDATA")
		}
		raw := string(rest[:end+3])
		content := string(rest[9:end])
		t.pos += end + 3
		t.countLines(raw)
		return &Token{Kind: TokenCData, Text: content, Raw: raw}, nil
	}
	// DOCTYPE
	if len(rest) >= 9 && strings.EqualFold(string(rest[:9]), "<!doctype") {
		// Read up to a balanced '>' (handle internal [])
		i := 9
		depth := 0
		for i < len(rest) {
			c := rest[i]
			if c == '[' {
				depth++
			} else if c == ']' {
				if depth > 0 {
					depth--
				}
			} else if c == '>' && depth == 0 {
				break
			}
			i++
		}
		if i >= len(rest) {
			return nil, t.errorf("unexpected EOF in DOCTYPE")
		}
		raw := string(rest[:i+1])
		content := string(rest[9:i]) // after "<!doctype"
		t.pos += i + 1
		t.countLines(raw)
		return &Token{Kind: TokenDoctype, Text: content, Raw: raw}, nil
	}
	// XML Decl <?xml ... ?>
	if len(rest) >= 5 && strings.EqualFold(string(rest[:5]), "<?xml") && (len(rest) == 5 || isSpace(rest[5])) {
		end := indexOfBytes(rest, []byte("?>"))
		if end < 0 {
			return nil, t.errorf("unexpected EOF in processing instruction")
		}
		raw := string(rest[:end+2])
		body := string(rest[5:end]) // everything between <?xml and ?>
		t.pos += end + 2
		t.countLines(raw)
		return &Token{Kind: TokenDecl, Name: "xml", Attrs: body, Raw: raw}, nil
	}
	// Processing instruction
	if len(rest) >= 2 && rest[1] == '?' {
		end := indexOfBytes(rest, []byte("?>"))
		if end < 0 {
			return nil, t.errorf("unexpected EOF in processing instruction")
		}
		// Parse <?target data?>
		inner := string(rest[2:end])
		name := inner
		data := ""
		for i, c := range inner {
			if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
				name = inner[:i]
				data = strings.TrimLeft(inner[i:], " \t\n\r")
				break
			}
		}
		raw := string(rest[:end+2])
		t.pos += end + 2
		t.countLines(raw)
		return &Token{Kind: TokenProcInst, Name: name, Attrs: data, Raw: raw}, nil
	}
	// End tag
	if len(rest) >= 2 && rest[1] == '/' {
		i := 2
		for i < len(rest) && rest[i] != '>' {
			i++
		}
		if i >= len(rest) {
			return nil, t.errorf("unexpected EOF")
		}
		name := strings.TrimSpace(string(rest[2:i]))
		if name == "" {
			return nil, t.errorf("expected element name after </")
		}
		raw := string(rest[:i+1])
		t.pos += i + 1
		t.countLines(raw)
		return &Token{Kind: TokenEnd, Name: name, Raw: raw}, nil
	}
	// Start or self-closing tag
	// Must have name char after '<'
	if len(rest) < 2 {
		return nil, t.errorf("unexpected EOF")
	}
	if !isNameStart(rest[1]) {
		return nil, t.errorf("expected element name after <")
	}
	// Read name
	i := 1
	for i < len(rest) && isNameChar(rest[i]) {
		i++
	}
	name := string(rest[1:i])
	// Read attributes / until '>' or '/>'
	attrStart := i
	selfClose := false
	inQuote := byte(0)
	for i < len(rest) {
		c := rest[i]
		if inQuote != 0 {
			if c == inQuote {
				inQuote = 0
			}
			i++
			continue
		}
		if c == '"' || c == '\'' {
			inQuote = c
			i++
			continue
		}
		if c == '/' && i+1 < len(rest) && rest[i+1] == '>' {
			selfClose = true
			break
		}
		if c == '>' {
			break
		}
		i++
	}
	if i >= len(rest) {
		return nil, t.errorf("unexpected EOF")
	}
	attrs := string(rest[attrStart:i])
	var raw string
	if selfClose {
		raw = string(rest[:i+2])
		t.pos += i + 2
	} else {
		raw = string(rest[:i+1])
		t.pos += i + 1
	}
	t.countLines(raw)
	kind := TokenStart
	if selfClose {
		kind = TokenSelfClose
	}
	return &Token{Kind: kind, Name: name, Attrs: attrs, Raw: raw}, nil
}

func isNameStart(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_' || c == ':'
}

func isNameChar(c byte) bool {
	return isNameStart(c) || (c >= '0' && c <= '9') || c == '-' || c == '.'
}

func isSpace(c byte) bool {
	return c == ' ' || c == '\t' || c == '\n' || c == '\r'
}

func indexOfBytes(src []byte, pat []byte) int {
	if len(pat) == 0 {
		return 0
	}
outer:
	for i := 0; i+len(pat) <= len(src); i++ {
		for j := 0; j < len(pat); j++ {
			if src[i+j] != pat[j] {
				continue outer
			}
		}
		return i
	}
	return -1
}

// ParseAttrs parses a raw attribute string into a slice of (name, value) pairs.
// It preserves leading whitespace between attributes (we just split).
func ParseAttrs(raw string) []struct{ Name, Value string } {
	var out []struct{ Name, Value string }
	i := 0
	for i < len(raw) {
		// skip spaces
		for i < len(raw) && (raw[i] == ' ' || raw[i] == '\t' || raw[i] == '\n' || raw[i] == '\r') {
			i++
		}
		if i >= len(raw) {
			break
		}
		// read name
		nameStart := i
		for i < len(raw) && raw[i] != '=' && raw[i] != ' ' && raw[i] != '\t' && raw[i] != '\n' && raw[i] != '\r' && raw[i] != '/' && raw[i] != '>' {
			i++
		}
		name := raw[nameStart:i]
		if name == "" {
			break
		}
		// check for '='
		for i < len(raw) && (raw[i] == ' ' || raw[i] == '\t' || raw[i] == '\n' || raw[i] == '\r') {
			i++
		}
		if i >= len(raw) || raw[i] != '=' {
			out = append(out, struct{ Name, Value string }{Name: name, Value: ""})
			continue
		}
		i++ // =
		for i < len(raw) && (raw[i] == ' ' || raw[i] == '\t' || raw[i] == '\n' || raw[i] == '\r') {
			i++
		}
		if i >= len(raw) {
			break
		}
		var val string
		if raw[i] == '"' || raw[i] == '\'' {
			q := raw[i]
			i++
			valStart := i
			for i < len(raw) && raw[i] != q {
				i++
			}
			val = raw[valStart:i]
			if i < len(raw) {
				i++ // closing quote
			}
		} else {
			valStart := i
			for i < len(raw) && raw[i] != ' ' && raw[i] != '\t' && raw[i] != '\n' && raw[i] != '\r' && raw[i] != '>' && raw[i] != '/' {
				i++
			}
			val = raw[valStart:i]
		}
		out = append(out, struct{ Name, Value string }{Name: name, Value: val})
	}
	return out
}
