	var b []byte
	var walk func(*Node)
	walk = func(n *Node) {
		switch n.Kind {
		case NodeText:
			b = append(b, decodeEntities(n.Text)...)
		case NodeCData:
			b = append(b, n.Text...)
		default:
			for _, c := range n.Children {
				walk(c)
			}
		}
	}
	walk(n)
	return string(b)
}

func decodeEntities(s string) string {
	if len(s) == 0 {
		return s
	}
	out := make([]byte, 0, len(s))
	for i := 0; i < len(s); {
		if s[i] != '&' {
			out = append(out, s[i])
			i++
			continue
		}
		// Find ';'
		end := -1
		for j := i + 1; j < len(s) && j < i+16; j++ {
			if s[j] == ';' {
				end = j
				break
			}
		}
		if end == -1 {
			out = append(out, s[i])
			i++
			continue
		}
		entity := s[i+1 : end]
		switch entity {
		case "amp":
			out = append(out, '&')
		case "lt":
			out = append(out, '<')
		case "gt":
			out = append(out, '>')
		case "quot":
			out = append(out, '"')
		case "apos":
			out = append(out, '\'')
		default:
			if len(entity) > 1 && entity[0] == '#' {
				var codepoint int
				if entity[1] == 'x' || entity[1] == 'X' {
					// hex
					for _, c := range entity[2:] {
						codepoint *= 16
						switch {
						case c >= '0' && c <= '9':
							codepoint += int(c - '0')
						case c >= 'a' && c <= 'f':
							codepoint += int(c-'a') + 10
						case c >= 'A' && c <= 'F':
							codepoint += int(c-'A') + 10
						default:
							codepoint = -1
						}
						if codepoint < 0 {
							break
						}
					}
				} else {
					for _, c := range entity[1:] {
						if c < '0' || c > '9' {
							codepoint = -1
							break
						}
						codepoint = codepoint*10 + int(c-'0')
					}
				}
				if codepoint > 0 {
					var buf [4]byte
					n := encodeRune(buf[:], rune(codepoint))
					out = append(out, buf[:n]...)
				} else {
					out = append(out, s[i:end+1]...)
				}
			} else {
				out = append(out, s[i:end+1]...)
			}
		}
		i = end + 1
	}
	return string(out)
}

// minimal UTF-8 encoder
func encodeRune(p []byte, r rune) int {
	switch {
	case r < 0x80:
		p[0] = byte(r)
		return 1
	case r < 0x800:
		p[0] = 0xc0 | byte(r>>6)
		p[1] = 0x80 | byte(r)&0x3f
		return 2
	case r < 0x10000:
		p[0] = 0xe0 | byte(r>>12)
		p[1] = 0x80 | byte(r>>6)&0x3f
		p[2] = 0x80 | byte(r)&0x3f
		return 3
	default:
		p[0] = 0xf0 | byte(r>>18)
		p[1] = 0x80 | byte(r>>12)&0x3f
		p[2] = 0x80 | byte(r>>6)&0x3f
		p[3] = 0x80 | byte(r)&0x3f
		return 4
	}
}
