			out = append(out, s[i])
			i++
			continue
		}
		entity := s[i+1 : end]
		switch entity {
		case "amp":
			out = append(out, '&')
		case "lt":
			out = append(out, '<')
		case "gt":
			out = append(out, '>')
		case "quot":
			out = append(out, '"')
		case "apos":
			out = append(out, '\'')
		default:
			if len(entity) > 1 && entity[0] == '#' {
				var codepoint int
				if entity[1] == 'x' || entity[1] == 'X' {
					// hex
					for _, c := range entity[2:] {
						codepoint *= 16
						switch {
						case c >= '0' && c <= '9':
							codepoint += int(c - '0')
						case c >= 'a' && c <= 'f':
							codepoint += int(c-'a') + 10
						case c >= 'A' && c <= 'F':
							codepoint += int(c-'A') + 10
						default:
							codepoint = -1
						}
						if codepoint < 0 {
							break
						}
					}
				} else {
					for _, c := range entity[1:] {
						if c < '0' || c > '9' {
							codepoint = -1
							break
						}
						codepoint = codepoint*10 + int(c-'0')
					}
				}
				if codepoint > 0 {
