package xmlparse

import (
	"fmt"
)

type NodeKind int

const (
	NodeDocument NodeKind = iota
	NodeElement
	NodeText
	NodeComment
	NodeCData
	NodeProcInst
	NodeDoctype
	NodeDecl
)

type Attr struct {
	Name  string
	Value string
}

type Node struct {
	Kind     NodeKind
	Name     string   // for Element
	Attrs    []Attr   // for Element/Decl/ProcInst
	AttrsRaw string   // original raw attribute string preserving spaces (without leading space trim)
	Text     string   // for Text, Comment, CData, Doctype (inner content)
	PITarget string   // for ProcInst
	PIData   string   // for ProcInst
	Children []*Node
	Parent   *Node
	// SelfClose indicates the element was written as <name/>
	SelfClose bool
}

// Parse parses XML into a tree.
func Parse(data []byte) (*Node, error) {
	t := New(data)
	root := &Node{Kind: NodeDocument}
	stack := []*Node{root}
	for {
		tok, err := t.Next()
		if err != nil {
			return nil, err
		}
		if tok == nil {
			break
		}
		parent := stack[len(stack)-1]
		switch tok.Kind {
		case TokenText:
			n := &Node{Kind: NodeText, Text: tok.Text, Parent: parent}
			parent.Children = append(parent.Children, n)
		case TokenComment:
			n := &Node{Kind: NodeComment, Text: tok.Text, Parent: parent}
			parent.Children = append(parent.Children, n)
		case TokenCData:
			n := &Node{Kind: NodeCData, Text: tok.Text, Parent: parent}
			parent.Children = append(parent.Children, n)
		case TokenDoctype:
			n := &Node{Kind: NodeDoctype, Text: tok.Text, Parent: parent}
			parent.Children = append(parent.Children, n)
		case TokenDecl:
			n := &Node{Kind: NodeDecl, Name: tok.Name, AttrsRaw: tok.Attrs, Parent: parent}
			n.Attrs = parseAttrsPairs(tok.Attrs)
			parent.Children = append(parent.Children, n)
		case TokenProcInst:
			n := &Node{Kind: NodeProcInst, PITarget: tok.Name, PIData: tok.Attrs, Parent: parent}
			parent.Children = append(parent.Children, n)
		case TokenSelfClose:
			n := &Node{Kind: NodeElement, Name: tok.Name, AttrsRaw: tok.Attrs, Parent: parent, SelfClose: true}
			n.Attrs = parseAttrsPairs(tok.Attrs)
			parent.Children = append(parent.Children, n)
		case TokenStart:
			n := &Node{Kind: NodeElement, Name: tok.Name, AttrsRaw: tok.Attrs, Parent: parent}
			n.Attrs = parseAttrsPairs(tok.Attrs)
			parent.Children = append(parent.Children, n)
			stack = append(stack, n)
		case TokenEnd:
			if len(stack) <= 1 {
				return nil, fmt.Errorf("XML syntax error on line %d: unexpected end element </%s>", t.line, tok.Name)
			}
			top := stack[len(stack)-1]
			if top.Name != tok.Name {
				return nil, fmt.Errorf("XML syntax error on line %d: element <%s> closed by </%s>", t.line, top.Name, tok.Name)
			}
			stack = stack[:len(stack)-1]
		}
	}
	if len(stack) > 1 {
		return nil, fmt.Errorf("XML syntax error on line %d: unexpected EOF", t.line)
	}
	return root, nil
}

func parseAttrsPairs(raw string) []Attr {
	pairs := ParseAttrs(raw)
	out := make([]Attr, 0, len(pairs))
	for _, p := range pairs {
		out = append(out, Attr{Name: p.Name, Value: p.Value})
	}
	return out
}

// Document root's first non-text child is the root element.
func (n *Node) RootElement() *Node {
	if n.Kind == NodeDocument {
		for _, c := range n.Children {
			if c.Kind == NodeElement {
				return c
			}
		}
	}
	return nil
}

// TextContent returns the concatenated text of the node and its descendants,
// decoding XML entities.
func (n *Node) TextContent() string {
	var b []byte
	var walk func(*Node)
	walk = func(n *Node) {
		switch n.Kind {
		case NodeText:
			b = append(b, decodeEntities(n.Text)...)
		case NodeCData:
			b = append(b, n.Text...)
		default:
			for _, c := range n.Children {
				walk(c)
			}
		}
	}
	walk(n)
	return string(b)
}

func decodeEntities(s string) string {
	if len(s) == 0 {
