		default:
			if len(entity) > 1 && entity[0] == '#' {
				var codepoint int
				if entity[1] == 'x' || entity[1] == 'X' {
					// hex
					for _, c := range entity[2:] {
						codepoint *= 16
						switch {
						case c >= '0' && c <= '9':
							codepoint += int(c - '0')
						case c >= 'a' && c <= 'f':
							codepoint += int(c-'a') + 10
						case c >= 'A' && c <= 'F':
