		if c {
			colorStart = ColorTag
			colorReset = ColorReset
		}
		// We want to color the <? and ?> but output attrs normally but values in green
		fmt.Fprintf(w, "%s<?%sxml", colorStart, colorReset)
		// Write attrs: we have n.Attrs
		writeAttrs(w, n.Attrs, c)
		fmt.Fprintf(w, "%s?>%s", colorStart, colorReset)
		io.WriteString(w, "\n")
	case xmlparse.NodeDoctype:
		c := opts.Color
		colorStart := ""
		colorReset := ""
		if c {
			colorStart = ColorTag
			colorReset = ColorReset
		}
		// Find name (first token after optional whitespace)
		content := strings.TrimLeft(n.Text, " \t")
		parts := strings.SplitN(content, " ", 2)
		name := parts[0]
		rest := ""
		if len(parts) > 1 {
			rest = " " + parts[1]
		}
		fmt.Fprintf(w, "%s<!doctype %s%s%s%s>%s\n", colorStart, colorReset, name, rest, colorStart, colorReset)
	case xmlparse.NodeComment:
		writeIndent(w, depth, opts)
		if opts.Color {
			io.WriteString(w, ColorComment)
		}
		io.WriteString(w, "<!--")
		io.WriteString(w, n.Text)
		io.WriteString(w, "-->")
		if opts.Color {
			io.WriteString(w, ColorReset)
		}
		io.WriteString(w, "\n")
	case xmlparse.NodeCData:
		writeIndent(w, depth, opts)
		if opts.Color {
			io.WriteString(w, ColorComment)
		}
		io.WriteString(w, "<![CDATA[")
		io.WriteString(w, n.Text)
		io.WriteString(w, "]]>")
		if opts.Color {
			io.WriteString(w, ColorReset)
		}
		io.WriteString(w, "\n")
	case xmlparse.NodeProcInst:
		writeIndent(w, depth, opts)
		c := opts.Color
		colorStart := ""
		colorReset := ""
		if c {
			colorStart = ColorTag
			colorReset = ColorReset
		}
		io.WriteString(w, colorStart)
		io.WriteString(w, "<?")
		io.WriteString(w, colorReset)
		io.WriteString(w, n.PITarget)
		if n.PIData != "" {
			io.WriteString(w, " ")
			io.WriteString(w, n.PIData)
		}
		io.WriteString(w, colorStart)
		io.WriteString(w, "?>")
		io.WriteString(w, colorReset)
	case xmlparse.NodeElement:
		writeElement(w, n, depth, opts, htmlMode)
	}
}

// Writes an element. Does not write the leading indentation or trailing newline;
// the caller is expected to handle those if needed.
func writeElement(w io.Writer, n *xmlparse.Node, depth int, opts Options, htmlMode bool) {
	c := opts.Color
	// Write start tag (we don't add indent here; caller adds)
	writeIndent(w, depth, opts)
	// Determine if element is empty (no children, or all children are empty text)
	hasRealChild := false
	for _, ch := range n.Children {
		switch ch.Kind {
		case xmlparse.NodeText:
			// count as real child only if non-empty, but for self-closing detection use length
			if len(ch.Text) > 0 {
				hasRealChild = true
			}
		default:
			hasRealChild = true
		}
	}
	// Write tag prefix
	if c {
		io.WriteString(w, ColorTag)
	}
	io.WriteString(w, "<")
	io.WriteString(w, n.Name)
	if c {
		io.WriteString(w, ColorReset)
	}
	writeAttrs(w, n.Attrs, c)
	// Decide if self-closing
	// XML: empty element becomes <name/>. HTML: stay as <name></name> except void elements.
	if !hasRealChild {
		if htmlMode {
			// Void elements always self-close; non-void keep as <name></name>
			// But our input may have been <name></name> - we need to know if it was originally.
			// From tokenizer: SelfClose indicates original was self-closing.
			if n.SelfClose || isVoidElement(n.Name) {
				if c {
					io.WriteString(w, ColorTag)
				}
				io.WriteString(w, "/>")
				if c {
					io.WriteString(w, ColorReset)
				}
			} else {
				if c {
					io.WriteString(w, ColorTag)
				}
				io.WriteString(w, ">")
				io.WriteString(w, "</")
				io.WriteString(w, n.Name)
				io.WriteString(w, ">")
				if c {
					io.WriteString(w, ColorReset)
				}
			}
		} else {
			// XML: self-close
			if c {
				io.WriteString(w, ColorTag)
			}
			io.WriteString(w, "/>")
			if c {
				io.WriteString(w, ColorReset)
			}
		}
		return
	}
	// Has real children. Close start tag.
	if c {
		io.WriteString(w, ColorTag)
	}
	io.WriteString(w, ">")
	if c {
		io.WriteString(w, ColorReset)
	}
	// Now format children.
	// Classify children
	writeElementChildren(w, n, depth, opts, htmlMode)
	// Closing tag
	if c {
		io.WriteString(w, ColorTag)
	}
	io.WriteString(w, "</")
	io.WriteString(w, n.Name)
	io.WriteString(w, ">")
	if c {
		io.WriteString(w, ColorReset)
	}
}

func writeElementChildren(w io.Writer, n *xmlparse.Node, depth int, opts Options, htmlMode bool) {
	// Strategy:
	// Determine if there is any element/comment/cdata child (a "block" child).
	// Classify text nodes: whitespace-only vs non-whitespace.
	// If only a single text child and no block children: inline.
	// If mixed: interleave. Each block child gets "\n" + indent(depth+1) prefix.
	// Non-whitespace text is kept inline (right-trimmed of spaces).
	// Whitespace-only text is removed.
	hasBlock := false
	for _, ch := range n.Children {
		if ch.Kind != xmlparse.NodeText {
			hasBlock = true
			break
		}
	}
	children := n.Children
	if !hasBlock {
		// Only text nodes
		// Concatenate and output inline
		var text string
		for _, ch := range children {
			text += ch.Text
		}
		// Trim trailing spaces (preserving tabs/newlines... actually based on earlier tests trim trailing ' ' only)
		text = trimTrailingSpaces(text)
		if opts.HTML || opts.Color || true {
			// Just print the text as-is for now
			io.WriteString(w, text)
		}
		return
	}
	// Mixed: at least one block child exists.
	// lastWasBlock and whether last written was text determines newline behavior before closing tag.
	// We'll iterate and build a queue.
	// For each child:
	//   - Block (element/comment/cdata/...): write "\n" + indent(depth+1) + block; recurse.
	//   - Text: write text (trimTrailingSpaces); if whitespace-only, skip.
	//   - Processing instruction: write "\n" + indent(depth+1) + PI.
	// At end:
	//   - If last written was a block (not text): write "\n" + indent(depth).
	//   - Else: nothing.
	lastWasText := false
	for _, ch := range children {
		switch ch.Kind {
		case xmlparse.NodeText:
			if isWhitespaceOnly(ch.Text) {
				// skip pure whitespace
				continue
			}
			// Output text (right-trim trailing spaces, but only before a block)
			// Actually we don't know yet if there's a block after; just trim trailing spaces at the end
			// of the text run. Doing it per-text might be fine.
			text := trimTrailingSpaces(ch.Text)
			io.WriteString(w, text)
			lastWasText = true
		case xmlparse.NodeElement, xmlparse.NodeComment, xmlparse.NodeCData, xmlparse.NodeProcInst:
			io.WriteString(w, "\n")
			writeNode(w, ch, depth+1, opts, htmlMode)
			if ch.Kind == xmlparse.NodeProcInst {
				// No newline after PI in output? Let's check; observed <?target data?></processinst>.
				// Actually we observed PI was output followed by whatever the next thing was; in one case
				// PI was followed by </processinst> with no newline.
				// So no trailing newline here.
			}
			lastWasText = false
		}
	}
	if !lastWasText {
		io.WriteString(w, "\n")
		writeIndent(w, depth, opts)
	}
}

func isVoidElement(name string) bool {
	switch strings.ToLower(name) {
	case "area", "base", "br", "col", "embed", "hr", "img", "input",
		"link", "meta", "param", "source", "track", "wbr":
		return true
	}
	return false
}
GOEOF
