package formatter

import (
	"fmt"
	"io"
	"strings"

	"xq/internal/xmlparse"
)

func FormatXML(data []byte, w io.Writer, opts Options) error {
	root, err := xmlparse.Parse(data)
	if err != nil {
		return err
	}
	writeNodes(w, root.Children, 0, opts, false)
	return nil
}

func writeNodes(w io.Writer, nodes []*xmlparse.Node, depth int, opts Options, htmlMode bool) {
	for i, n := range nodes {
		writeNode(w, n, depth, opts, htmlMode)
		if n.Kind == xmlparse.NodeElement {
			// Root-level element: add newline after
			if i == len(nodes)-1 || true {
				io.WriteString(w, "\n")
			}
		}
	}
}

func writeIndent(w io.Writer, depth int, opts Options) {
	io.WriteString(w, strings.Repeat(opts.Indent, depth))
}

func trimTrailingSpaces(s string) string {
	n := len(s)
	for n > 0 && s[n-1] == ' ' {
		n--
	}
	return s[:n]
}

func isWhitespaceOnly(s string) bool {
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c != ' ' && c != '\t' && c != '\n' && c != '\r' {
			return false
		}
	}
	return true
}

func writeAttrs(w io.Writer, attrs []xmlparse.Attr, enable bool) {
	for _, a := range attrs {
		io.WriteString(w, " ")
		io.WriteString(w, a.Name)
		if enable {
			io.WriteString(w, ColorAttr)
		}
		io.WriteString(w, "=\"")
		io.WriteString(w, a.Value)
		io.WriteString(w, "\"")
		if enable {
			io.WriteString(w, ColorReset)
		}
	}
}

func writeNode(w io.Writer, n *xmlparse.Node, depth int, opts Options, htmlMode bool) {
	switch n.Kind {
	case xmlparse.NodeDecl:
		colorStart := ""
		colorReset := ""
		if opts.Color {
			colorStart = ColorTag
			colorReset = ColorReset
		}
		fmt.Fprintf(w, "%s<?%sxml", colorStart, colorReset)
		writeAttrs(w, n.Attrs, opts.Color)
		fmt.Fprintf(w, "%s?>%s", colorStart, colorReset)
	case xmlparse.NodeDoctype:
		colorStart := ""
		colorReset := ""
		if opts.Color {
			colorStart = ColorTag
			colorReset = ColorReset
		}
		// Lowercase DOCTYPE in output
		// n.Text is content after "<!DOCTYPE" (preserving case from source, but we already matched case-insensitive)
		content := n.Text
		// Trim leading space (we want output: "<!doctype NAME ...>")
		trimmed := strings.TrimLeft(content, " \t")
		fmt.Fprintf(w, "%s<!doctype %s%s%s>%s", colorStart, colorReset, trimmed, colorStart, colorReset)
	case xmlparse.NodeComment:
		writeIndent(w, depth, opts)
		if opts.Color {
			io.WriteString(w, ColorComment)
		}
		io.WriteString(w, "<!--")
		io.WriteString(w, n.Text)
		io.WriteString(w, "-->")
		if opts.Color {
			io.WriteString(w, ColorReset)
		}
	case xmlparse.NodeCData:
		writeIndent(w, depth, opts)
		if opts.Color {
			io.WriteString(w, ColorComment)
		}
		io.WriteString(w, "<![CDATA[")
		io.WriteString(w, n.Text)
		io.WriteString(w, "]]>")
		if opts.Color {
			io.WriteString(w, ColorReset)
		}
	case xmlparse.NodeProcInst:
		writeIndent(w, depth, opts)
		colorStart := ""
		colorReset := ""
		if opts.Color {
			colorStart = ColorTag
			colorReset = ColorReset
		}
		io.WriteString(w, colorStart)
		io.WriteString(w, "<?")
		io.WriteString(w, colorReset)
		io.WriteString(w, n.PITarget)
		if n.PIData != "" {
			io.WriteString(w, " ")
			io.WriteString(w, n.PIData)
		}
		io.WriteString(w, colorStart)
		io.WriteString(w, "?>")
		io.WriteString(w, colorReset)
	case xmlparse.NodeElement:
		writeElement(w, n, depth, opts, htmlMode)
	}
}

func writeElement(w io.Writer, n *xmlparse.Node, depth int, opts Options, htmlMode bool) {
	writeIndent(w, depth, opts)
	// Determine "has real child"
	hasRealChild := false
	for _, ch := range n.Children {
		if ch.Kind == xmlparse.NodeText {
			if len(ch.Text) > 0 {
				hasRealChild = true
			}
		} else {
			hasRealChild = true
		}
	}
	if opts.Color {
		io.WriteString(w, ColorTag)
	}
	io.WriteString(w, "<")
	io.WriteString(w, n.Name)
	if opts.Color {
		io.WriteString(w, ColorReset)
	}
	writeAttrs(w, n.Attrs, opts.Color)
	if !hasRealChild {
		if htmlMode {
			if n.SelfClose || isVoidElement(n.Name) {
				if opts.Color {
					io.WriteString(w, ColorTag)
				}
				io.WriteString(w, "/>")
				if opts.Color {
					io.WriteString(w, ColorReset)
				}
			} else {
				if opts.Color {
					io.WriteString(w, ColorTag)
				}
				io.WriteString(w, ">")
				io.WriteString(w, "</")
				io.WriteString(w, n.Name)
				io.WriteString(w, ">")
				if opts.Color {
					io.WriteString(w, ColorReset)
				}
			}
		} else {
			if opts.Color {
				io.WriteString(w, ColorTag)
			}
			io.WriteString(w, "/>")
			if opts.Color {
				io.WriteString(w, ColorReset)
			}
		}
		return
	}
	if opts.Color {
		io.WriteString(w, ColorTag)
	}
	io.WriteString(w, ">")
	if opts.Color {
		io.WriteString(w, ColorReset)
	}
	writeElementChildren(w, n, depth, opts, htmlMode)
	if opts.Color {
		io.WriteString(w, ColorTag)
	}
	io.WriteString(w, "</")
	io.WriteString(w, n.Name)
	io.WriteString(w, ">")
	if opts.Color {
		io.WriteString(w, ColorReset)
	}
}

func writeElementChildren(w io.Writer, n *xmlparse.Node, depth int, opts Options, htmlMode bool) {
	hasBlock := false
	for _, ch := range n.Children {
		if ch.Kind != xmlparse.NodeText {
			hasBlock = true
			break
		}
	}
	if !hasBlock {
		var text string
		for _, ch := range n.Children {
			text += ch.Text
		}
		text = trimTrailingSpaces(text)
		io.WriteString(w, text)
		return
	}
	// Mixed
	lastWasText := false
	for _, ch := range n.Children {
		switch ch.Kind {
		case xmlparse.NodeText:
			if isWhitespaceOnly(ch.Text) {
				continue
			}
			text := trimTrailingSpaces(ch.Text)
			io.WriteString(w, text)
			lastWasText = true
		case xmlparse.NodeElement, xmlparse.NodeComment, xmlparse.NodeCData, xmlparse.NodeProcInst:
			io.WriteString(w, "\n")
			writeNode(w, ch, depth+1, opts, htmlMode)
			lastWasText = false
		}
	}
	if !lastWasText {
		io.WriteString(w, "\n")
		writeIndent(w, depth, opts)
	}
}

func isVoidElement(name string) bool {
	switch strings.ToLower(name) {
	case "area", "base", "br", "col", "embed", "hr", "img", "input",
		"link", "meta", "param", "source", "track", "wbr":
		return true
	}
	return false
}
