package jsonfmt

import (
	"errors"
	"fmt"
	"io"
	"strconv"
	"strings"
	"unicode/utf16"
	"unicode/utf8"
)

// OrderedMap preserves insertion order.
type OrderedMap struct {
	Keys   []string
	Values map[string]interface{}
}

func NewOrderedMap() *OrderedMap {
	return &OrderedMap{Values: map[string]interface{}{}}
}

func (m *OrderedMap) Set(k string, v interface{}) {
	if _, ok := m.Values[k]; !ok {
		m.Keys = append(m.Keys, k)
	}
	m.Values[k] = v
}

func (m *OrderedMap) Get(k string) (interface{}, bool) {
	v, ok := m.Values[k]
	return v, ok
}

// Parse parses a JSON document preserving object key order.
// Returns the parsed value and any error.
func Parse(data []byte) (interface{}, error) {
	p := &parser{src: data}
	p.skipWS()
	v, err := p.parseValue()
	if err != nil {
		return nil, err
	}
	p.skipWS()
	if p.pos < len(p.src) {
		return nil, fmt.Errorf("invalid character %q after top-level value", string(p.src[p.pos]))
	}
	return v, nil
}

type parser struct {
	src []byte
	pos int
}

func (p *parser) skipWS() {
	for p.pos < len(p.src) {
		c := p.src[p.pos]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			p.pos++
		} else {
			break
		}
	}
}

func (p *parser) parseValue() (interface{}, error) {
	p.skipWS()
	if p.pos >= len(p.src) {
		return nil, errors.New("unexpected end of JSON input")
	}
	c := p.src[p.pos]
	switch {
	case c == '{':
		return p.parseObject()
	case c == '[':
		return p.parseArray()
	case c == '"':
		return p.parseString()
	case c == 't' || c == 'f':
		return p.parseBool()
	case c == 'n':
		return p.parseNull()
	case c == '-' || (c >= '0' && c <= '9'):
		return p.parseNumber()
	}
	return nil, fmt.Errorf("invalid character %q looking for beginning of value", string(c))
}

func (p *parser) parseObject() (*OrderedMap, error) {
	p.pos++ // consume '{'
	m := NewOrderedMap()
	p.skipWS()
	if p.pos < len(p.src) && p.src[p.pos] == '}' {
		p.pos++
		return m, nil
	}
	for {
		p.skipWS()
		if p.pos >= len(p.src) || p.src[p.pos] != '"' {
			return nil, errors.New("expected string key")
		}
		k, err := p.parseString()
		if err != nil {
			return nil, err
		}
		p.skipWS()
		if p.pos >= len(p.src) || p.src[p.pos] != ':' {
			return nil, errors.New("expected ':' after key")
		}
		p.pos++
		v, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		m.Set(k, v)
		p.skipWS()
		if p.pos >= len(p.src) {
			return nil, errors.New("unexpected end of JSON input in object")
		}
		if p.src[p.pos] == ',' {
			p.pos++
			continue
		}
		if p.src[p.pos] == '}' {
			p.pos++
			return m, nil
		}
		return nil, fmt.Errorf("expected ',' or '}' got %q", string(p.src[p.pos]))
	}
}

func (p *parser) parseArray() ([]interface{}, error) {
	p.pos++ // [
	arr := []interface{}{}
	p.skipWS()
	if p.pos < len(p.src) && p.src[p.pos] == ']' {
		p.pos++
		return arr, nil
	}
	for {
		v, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		arr = append(arr, v)
		p.skipWS()
		if p.pos >= len(p.src) {
			return nil, errors.New("unexpected end of JSON input in array")
		}
		if p.src[p.pos] == ',' {
			p.pos++
			continue
		}
		if p.src[p.pos] == ']' {
			p.pos++
			return arr, nil
		}
		return nil, fmt.Errorf("expected ',' or ']' got %q", string(p.src[p.pos]))
	}
}

func (p *parser) parseString() (string, error) {
	p.pos++ // "
	var b strings.Builder
	for p.pos < len(p.src) {
		c := p.src[p.pos]
		if c == '"' {
			p.pos++
			return b.String(), nil
		}
		if c == '\\' {
			p.pos++
			if p.pos >= len(p.src) {
				return "", errors.New("unexpected end of string")
			}
			esc := p.src[p.pos]
			p.pos++
			switch esc {
			case '"', '\\', '/':
				b.WriteByte(esc)
			case 'b':
				b.WriteByte('\b')
			case 'f':
				b.WriteByte('\f')
			case 'n':
				b.WriteByte('\n')
			case 'r':
				b.WriteByte('\r')
			case 't':
				b.WriteByte('\t')
			case 'u':
				if p.pos+4 > len(p.src) {
					return "", errors.New("bad unicode escape")
				}
				h := string(p.src[p.pos : p.pos+4])
				p.pos += 4
				v, err := strconv.ParseUint(h, 16, 32)
				if err != nil {
					return "", err
				}
				r := rune(v)
				// surrogate pair
				if utf16.IsSurrogate(r) && p.pos+6 <= len(p.src) && p.src[p.pos] == '\\' && p.src[p.pos+1] == 'u' {
					h2 := string(p.src[p.pos+2 : p.pos+6])
					v2, err := strconv.ParseUint(h2, 16, 32)
					if err == nil {
						r = utf16.DecodeRune(r, rune(v2))
						p.pos += 6
					}
				}
				var buf [4]byte
				n := utf8.EncodeRune(buf[:], r)
				b.Write(buf[:n])
			default:
				return "", fmt.Errorf("bad escape \\%c", esc)
			}
			continue
		}
		b.WriteByte(c)
		p.pos++
	}
	return "", errors.New("unterminated string")
}

func (p *parser) parseBool() (bool, error) {
	if p.pos+4 <= len(p.src) && string(p.src[p.pos:p.pos+4]) == "true" {
		p.pos += 4
		return true, nil
	}
	if p.pos+5 <= len(p.src) && string(p.src[p.pos:p.pos+5]) == "false" {
		p.pos += 5
		return false, nil
	}
	return false, errors.New("invalid bool")
}

func (p *parser) parseNull() (interface{}, error) {
	if p.pos+4 <= len(p.src) && string(p.src[p.pos:p.pos+4]) == "null" {
		p.pos += 4
		return nil, nil
	}
	return nil, errors.New("invalid null")
}

// Number represents a JSON number, preserved as raw string.
type Number string

func (n Number) String() string { return string(n) }

func (p *parser) parseNumber() (Number, error) {
	start := p.pos
	if p.src[p.pos] == '-' {
		p.pos++
	}
	for p.pos < len(p.src) && p.src[p.pos] >= '0' && p.src[p.pos] <= '9' {
		p.pos++
	}
	if p.pos < len(p.src) && p.src[p.pos] == '.' {
		p.pos++
		for p.pos < len(p.src) && p.src[p.pos] >= '0' && p.src[p.pos] <= '9' {
			p.pos++
		}
	}
	if p.pos < len(p.src) && (p.src[p.pos] == 'e' || p.src[p.pos] == 'E') {
		p.pos++
		if p.pos < len(p.src) && (p.src[p.pos] == '+' || p.src[p.pos] == '-') {
			p.pos++
		}
		for p.pos < len(p.src) && p.src[p.pos] >= '0' && p.src[p.pos] <= '9' {
			p.pos++
		}
	}
	return Number(p.src[start:p.pos]), nil
}

// Marshal options
type MarshalOptions struct {
	Indent  string // if empty and Compact true → no indent
	Compact bool
}

// Marshal writes value v to w using options.
func Marshal(w io.Writer, v interface{}, opts MarshalOptions) error {
	return writeValue(w, v, opts, 0)
}

func writeValue(w io.Writer, v interface{}, opts MarshalOptions, depth int) error {
	switch x := v.(type) {
	case nil:
		io.WriteString(w, "null")
	case bool:
		if x {
			io.WriteString(w, "true")
		} else {
			io.WriteString(w, "false")
		}
	case string:
		writeJSONString(w, x)
	case Number:
		io.WriteString(w, string(x))
	case float64:
		io.WriteString(w, strconv.FormatFloat(x, 'g', -1, 64))
	case int:
		io.WriteString(w, strconv.Itoa(x))
	case *OrderedMap:
		writeObject(w, x, opts, depth)
	case []interface{}:
		writeArray(w, x, opts, depth)
	default:
		return fmt.Errorf("unsupported type %T", v)
	}
	return nil
}

func writeObject(w io.Writer, m *OrderedMap, opts MarshalOptions, depth int) {
	if len(m.Keys) == 0 {
		io.WriteString(w, "{}")
		return
	}
	io.WriteString(w, "{")
	for i, k := range m.Keys {
		if i > 0 {
			io.WriteString(w, ",")
		}
		if !opts.Compact {
			io.WriteString(w, "\n")
			io.WriteString(w, strings.Repeat(opts.Indent, depth+1))
		}
		writeJSONString(w, k)
		io.WriteString(w, ": ")
		writeValue(w, m.Values[k], opts, depth+1)
	}
	if !opts.Compact {
		io.WriteString(w, "\n")
		io.WriteString(w, strings.Repeat(opts.Indent, depth))
	}
	io.WriteString(w, "}")
}

func writeArray(w io.Writer, arr []interface{}, opts MarshalOptions, depth int) {
	if len(arr) == 0 {
		io.WriteString(w, "[]")
		return
	}
	io.WriteString(w, "[")
	for i, v := range arr {
		if i > 0 {
			io.WriteString(w, ",")
		}
		if !opts.Compact {
			io.WriteString(w, "\n")
			io.WriteString(w, strings.Repeat(opts.Indent, depth+1))
		}
		writeValue(w, v, opts, depth+1)
	}
	if !opts.Compact {
		io.WriteString(w, "\n")
		io.WriteString(w, strings.Repeat(opts.Indent, depth))
	}
	io.WriteString(w, "]")
}

func writeJSONString(w io.Writer, s string) {
	io.WriteString(w, "\"")
	for _, r := range s {
		switch r {
		case '"':
			io.WriteString(w, "\\\"")
		case '\\':
			io.WriteString(w, "\\\\")
		case '\b':
			io.WriteString(w, "\\b")
		case '\f':
			io.WriteString(w, "\\f")
		case '\n':
			io.WriteString(w, "\\n")
		case '\r':
			io.WriteString(w, "\\r")
		case '\t':
			io.WriteString(w, "\\t")
		default:
			if r < 0x20 {
				fmt.Fprintf(w, "\\u%04x", r)
			} else {
				fmt.Fprintf(w, "%c", r)
			}
		}
	}
	io.WriteString(w, "\"")
}
