func (p *parser) parseNull() (interface{}, error) {
	if p.pos+4 <= len(p.src) && string(p.src[p.pos:p.pos+4]) == "null" {
		p.pos += 4
		return nil, nil
	}
	return nil, errors.New("invalid null")
}

// Number represents a JSON number, preserved as raw string.
type Number string

func (n Number) String() string { return string(n) }

func (p *parser) parseNumber() (Number, error) {
	start := p.pos
	if p.src[p.pos] == '-' {
		p.pos++
	}
	for p.pos < len(p.src) && p.src[p.pos] >= '0' && p.src[p.pos] <= '9' {
		p.pos++
	}
	if p.pos < len(p.src) && p.src[p.pos] == '.' {
		p.pos++
		for p.pos < len(p.src) && p.src[p.pos] >= '0' && p.src[p.pos] <= '9' {
			p.pos++
		}
	}
	if p.pos < len(p.src) && (p.src[p.pos] == 'e' || p.src[p.pos] == 'E') {
		p.pos++
		if p.pos < len(p.src) && (p.src[p.pos] == '+' || p.src[p.pos] == '-') {
			p.pos++
		}
		for p.pos < len(p.src) && p.src[p.pos] >= '0' && p.src[p.pos] <= '9' {
			p.pos++
		}
	}
	return Number(p.src[start:p.pos]), nil
}

// Marshal options
type MarshalOptions struct {
	Indent  string // if empty and Compact true → no indent
	Compact bool
}

// Marshal writes value v to w using options.
func Marshal(w io.Writer, v interface{}, opts MarshalOptions) error {
	return writeValue(w, v, opts, 0)
}

func writeValue(w io.Writer, v interface{}, opts MarshalOptions, depth int) error {
	switch x := v.(type) {
	case nil:
		io.WriteString(w, "null")
	case bool:
		if x {
			io.WriteString(w, "true")
		} else {
			io.WriteString(w, "false")
		}
	case string:
		writeJSONString(w, x)
	case Number:
		io.WriteString(w, string(x))
	case float64:
		io.WriteString(w, strconv.FormatFloat(x, 'g', -1, 64))
	case int:
		io.WriteString(w, strconv.Itoa(x))
	case *OrderedMap:
		writeObject(w, x, opts, depth)
	case []interface{}:
		writeArray(w, x, opts, depth)
	default:
		return fmt.Errorf("unsupported type %T", v)
	}
	return nil
}

func writeObject(w io.Writer, m *OrderedMap, opts MarshalOptions, depth int) {
	if len(m.Keys) == 0 {
		io.WriteString(w, "{}")
		return
	}
	io.WriteString(w, "{")
	for i, k := range m.Keys {
		if i > 0 {
			io.WriteString(w, ",")
		}
		if !opts.Compact {
			io.WriteString(w, "\n")
			io.WriteString(w, strings.Repeat(opts.Indent, depth+1))
		}
		writeJSONString(w, k)
		io.WriteString(w, ": ")
		writeValue(w, m.Values[k], opts, depth+1)
	}
	if !opts.Compact {
		io.WriteString(w, "\n")
		io.WriteString(w, strings.Repeat(opts.Indent, depth))
	}
	io.WriteString(w, "}")
}

func writeArray(w io.Writer, arr []interface{}, opts MarshalOptions, depth int) {
	if len(arr) == 0 {
		io.WriteString(w, "[]")
		return
	}
	io.WriteString(w, "[")
	for i, v := range arr {
		if i > 0 {
			io.WriteString(w, ",")
		}
		if !opts.Compact {
			io.WriteString(w, "\n")
			io.WriteString(w, strings.Repeat(opts.Indent, depth+1))
		}
		writeValue(w, v, opts, depth+1)
	}
	if !opts.Compact {
		io.WriteString(w, "\n")
		io.WriteString(w, strings.Repeat(opts.Indent, depth))
	}
	io.WriteString(w, "]")
}

func writeJSONString(w io.Writer, s string) {
	io.WriteString(w, "\"")
	for _, r := range s {
		switch r {
		case '"':
			io.WriteString(w, "\\\"")
		case '\\':
			io.WriteString(w, "\\\\")
		case '\b':
			io.WriteString(w, "\\b")
		case '\f':
			io.WriteString(w, "\\f")
		case '\n':
			io.WriteString(w, "\\n")
		case '\r':
			io.WriteString(w, "\\r")
		case '\t':
			io.WriteString(w, "\\t")
		default:
			if r < 0x20 {
				fmt.Fprintf(w, "\\u%04x", r)
			} else {
				fmt.Fprintf(w, "%c", r)
			}
		}
	}
	io.WriteString(w, "\"")
}
