	}
	err = jsonfmt.Marshal(w, v, jsonfmt.MarshalOptions{Indent: indent, Compact: false})
	if err == nil {
		io.WriteString(w, "\n")
	}
	return err
}

// XMLToJSON converts an XML document to JSON (as the tool does).
func XMLToJSON(data []byte, w io.Writer, opts Options) error {
	root, err := xmlparse.Parse(data)
	if err != nil {
		// try JSON
		_, jerr := jsonfmt.Parse(data)
		if jerr != nil {
			return fmt.Errorf("error while parsing JSON: %s", jerr.Error())
		}
		return err
	}
	elem := root.RootElement()
	if elem == nil {
		io.WriteString(w, "{}")
		if !opts.Compact {
			io.WriteString(w, "\n")
		}
		return nil
	}
	topMap := jsonfmt.NewOrderedMap()
	topMap.Set(elem.Name, elementToJSON(elem, opts.Depth, 0))
	indent := "  "
	if err := jsonfmt.Marshal(w, topMap, jsonfmt.MarshalOptions{Indent: indent, Compact: opts.Compact}); err != nil {
		return err
	}
	io.WriteString(w, "\n")
	return nil
}

// elementToJSON converts an element to its JSON representation.
// depthLimit: -1 = unlimited. If depthLimit == currentDepth, flatten to text.
func elementToJSON(n *xmlparse.Node, depthLimit, currentDepth int) interface{} {
	if depthLimit >= 0 && currentDepth >= depthLimit {
		return flattenText(n)
	}
	// Check if element has only text children and no attrs (then string)
	// Count attributes and element children
	hasAttrs := len(n.Attrs) > 0
	hasElemChild := false
	allTextOrOther := true
	var texts []string
	for _, c := range n.Children {
		switch c.Kind {
		case xmlparse.NodeElement:
			hasElemChild = true
			allTextOrOther = false
		case xmlparse.NodeText:
			if !isWhitespaceOnly(c.Text) {
				texts = append(texts, xmlparse.DecodeEntities(c.Text))
			}
		case xmlparse.NodeCData:
			texts = append(texts, c.Text)
		}
	}
	_ = allTextOrOther
	if !hasAttrs && !hasElemChild {
		return strings.Join(texts, "")
	}
	// Build ordered map
	m := jsonfmt.NewOrderedMap()
	// Attrs first (in order)
	for _, a := range n.Attrs {
		m.Set("@"+a.Name, a.Value)
	}
	// #text if there are text nodes and we have attrs or elem children
	if len(texts) > 0 && hasElemChild {
		m.Set("#text", strings.Join(texts, "\n"))
	} else if len(texts) > 0 && hasAttrs && !hasElemChild {
		m.Set("#text", strings.Join(texts, ""))
	}
	// Group child elements by name, alphabetical order per-group order? Observed: alpha order for keys.
	groups := map[string][]*xmlparse.Node{}
	var keyOrder []string
	// According to observation: JSON output uses alphabetical key order for XML→JSON
	// But let's preserve input order first, then sort alphabetically overall at end.
	for _, c := range n.Children {
		if c.Kind != xmlparse.NodeElement {
			continue
		}
		if _, ok := groups[c.Name]; !ok {
			keyOrder = append(keyOrder, c.Name)
		}
		groups[c.Name] = append(groups[c.Name], c)
	}
	// Sort alphabetically
	sortStrings(keyOrder)
	for _, k := range keyOrder {
		children := groups[k]
		if len(children) == 1 {
			m.Set(k, elementToJSON(children[0], depthLimit, currentDepth+1))
		} else {
			arr := make([]interface{}, 0, len(children))
			for _, cc := range children {
				arr = append(arr, elementToJSON(cc, depthLimit, currentDepth+1))
			}
			m.Set(k, arr)
		}
	}
	return m
}

func flattenText(n *xmlparse.Node) string {
	var parts []string
	var walk func(*xmlparse.Node)
	walk = func(n *xmlparse.Node) {
		switch n.Kind {
		case xmlparse.NodeText:
			if !isWhitespaceOnly(n.Text) {
				parts = append(parts, xmlparse.DecodeEntities(n.Text))
			}
		case xmlparse.NodeCData:
			parts = append(parts, n.Text)
		default:
			for _, c := range n.Children {
				walk(c)
			}
		}
	}
	walk(n)
	return strings.Join(parts, "\n")
}

func sortStrings(a []string) {
	// simple insertion sort (small slices)
	for i := 1; i < len(a); i++ {
		j := i
		for j > 0 && a[j-1] > a[j] {
			a[j-1], a[j] = a[j], a[j-1]
			j--
		}
	}
}
