			io.WriteString(w, v)
			io.WriteString(w, "\n")
		}
		return nil
	}
	writeQueryResult(w, nodes, opts)
	return nil
}

func writeQueryResult(w io.Writer, nodes []*xmlparse.Node, opts Options) {
	for _, n := range nodes {
		if opts.Node {
			// Write the node as XML
			writeNode(w, n, 0, opts, opts.HTML)
			io.WriteString(w, "\n")
		} else {
			io.WriteString(w, n.TextContent())
			io.WriteString(w, "\n")
		}
	}
}

// evaluateXPath handles a subset of XPath.
// Returns element nodes and/or attribute values.
func evaluateXPath(root *xmlparse.Node, expr string) ([]*xmlparse.Node, []string) {
	expr = strings.TrimSpace(expr)
	// Handle attribute extraction at end: "/@attr"
	attrName := ""
	if idx := strings.LastIndex(expr, "/@"); idx >= 0 {
		attrName = expr[idx+2:]
		expr = expr[:idx]
	} else if strings.HasPrefix(expr, "@") {
		attrName = expr[1:]
		expr = ""
	}

	var nodes []*xmlparse.Node
	if expr == "" || expr == "/" {
		elem := root.RootElement()
		if elem != nil {
			nodes = append(nodes, elem)
		}
	} else {
		nodes = matchPath(root, expr)
	}

	if attrName != "" {
		var values []string
		for _, n := range nodes {
			for _, a := range n.Attrs {
				if a.Name == attrName {
					values = append(values, a.Value)
				}
			}
		}
		return nil, values
	}
	return nodes, nil
}

// matchPath evaluates a simplified XPath expression.
func matchPath(root *xmlparse.Node, expr string) []*xmlparse.Node {
	// Split into segments. Support "//" for descendant.
	// We parse segments with their axis.
	type seg struct {
		name       string
		descendant bool
		preds      []string // predicate expressions like "[@id='x']" content, without brackets
	}
	var segs []seg
	i := 0
	descendant := true
	// starts with '/' or '//' or relative
	if strings.HasPrefix(expr, "//") {
		i = 2
		descendant = true
	} else if strings.HasPrefix(expr, "/") {
		i = 1
		descendant = false
	}
	for i < len(expr) {
		// parse name
		nameStart := i
		for i < len(expr) && expr[i] != '/' && expr[i] != '[' {
			i++
		}
		name := expr[nameStart:i]
		var preds []string
		for i < len(expr) && expr[i] == '[' {
			depth := 1
			i++
			predStart := i
			for i < len(expr) && depth > 0 {
				if expr[i] == '[' {
					depth++
				} else if expr[i] == ']' {
					depth--
					if depth == 0 {
						break
					}
				}
				i++
			}
			preds = append(preds, expr[predStart:i])
			if i < len(expr) && expr[i] == ']' {
				i++
			}
		}
		segs = append(segs, seg{name: name, descendant: descendant, preds: preds})
		descendant = false
		if i < len(expr) && expr[i] == '/' {
			i++
			if i < len(expr) && expr[i] == '/' {
				descendant = true
				i++
			}
		}
	}
	// Apply from root
	var current []*xmlparse.Node
	// Start: root element children of document
	doc := root
	if doc.Kind == xmlparse.NodeDocument {
		for _, c := range doc.Children {
			if c.Kind == xmlparse.NodeElement {
				current = append(current, c)
			}
		}
	} else {
		current = []*xmlparse.Node{doc}
	}
	// For the first segment with descendant=true, we need to also include descendants.
	for idx, s := range segs {
		var next []*xmlparse.Node
		if s.descendant {
			// Collect all descendants matching name (including self or starting from root?)
			if idx == 0 {
				// For //name, include the starting element and all descendants
				collectDescendants(doc, s.name, &next, true)
			} else {
				for _, c := range current {
					collectDescendants(c, s.name, &next, false)
				}
			}
		} else {
			if idx == 0 {
				// /name - match root element name
				for _, c := range current {
					if nameMatches(s.name, c.Name) {
						next = append(next, c)
					}
				}
			} else {
				for _, c := range current {
					for _, cc := range c.Children {
						if cc.Kind == xmlparse.NodeElement && nameMatches(s.name, cc.Name) {
							next = append(next, cc)
						}
					}
				}
			}
		}
		// Apply predicates
		for _, p := range s.preds {
			next = applyPredicate(next, p)
		}
		current = next
	}
	return current
}

func nameMatches(pat, name string) bool {
	if pat == "*" || pat == "" {
		return true
	}
	return pat == name
}

func collectDescendants(n *xmlparse.Node, name string, out *[]*xmlparse.Node, includeSelf bool) {
	if n.Kind == xmlparse.NodeElement {
		if includeSelf && nameMatches(name, n.Name) {
			*out = append(*out, n)
		}
	}
	for _, c := range n.Children {
		if c.Kind == xmlparse.NodeElement && nameMatches(name, c.Name) {
			*out = append(*out, c)
		}
	}
	for _, c := range n.Children {
		collectDescendants(c, name, out, false)
	}
}

func applyPredicate(nodes []*xmlparse.Node, pred string) []*xmlparse.Node {
	pred = strings.TrimSpace(pred)
	// Numeric index: [N]
	if n, ok := parseIntSimple(pred); ok {
		if n >= 1 && n <= len(nodes) {
			return []*xmlparse.Node{nodes[n-1]}
		}
		return nil
	}
	// @attr="value" or @attr
	if strings.HasPrefix(pred, "@") {
		// [@attr] or [@attr="v"] or [@attr='v']
		rest := pred[1:]
		eqIdx := strings.Index(rest, "=")
		attrName := rest
		wantValue := ""
		checkValue := false
		if eqIdx >= 0 {
			attrName = strings.TrimSpace(rest[:eqIdx])
			val := strings.TrimSpace(rest[eqIdx+1:])
			if len(val) >= 2 && (val[0] == '"' || val[0] == '\'') && val[len(val)-1] == val[0] {
				wantValue = val[1 : len(val)-1]
				checkValue = true
			}
		}
		var out []*xmlparse.Node
		for _, n := range nodes {
			for _, a := range n.Attrs {
				if a.Name == attrName {
					if !checkValue || a.Value == wantValue {
						out = append(out, n)
					}
					break
				}
			}
		}
		return out
	}
	// Unknown predicate: return as-is
	return nodes
}

func parseIntSimple(s string) (int, bool) {
	if s == "" {
		return 0, false
	}
	n := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c < '0' || c > '9' {
			return 0, false
		}
		n = n*10 + int(c-'0')
	}
	return n, true
}

// CSS selector implementation (very basic)
func QueryCSS(data []byte, w io.Writer, opts Options) error {
	root, err := xmlparse.Parse(data)
	if err != nil {
		return err
	}
	nodes := matchCSS(root, opts.Query)
	if opts.Attr != "" {
		for _, n := range nodes {
			for _, a := range n.Attrs {
				if a.Name == opts.Attr {
					io.WriteString(w, a.Value)
					io.WriteString(w, "\n")
					break
				}
			}
		}
		return nil
	}
	writeQueryResult(w, nodes, opts)
	return nil
}

func matchCSS(root *xmlparse.Node, query string) []*xmlparse.Node {
	// Split selector by commas for union
	var result []*xmlparse.Node
	for _, sel := range splitSelectors(query, ",") {
		sel = strings.TrimSpace(sel)
		res := matchSingleSelector(root, sel)
		result = append(result, res...)
	}
	return result
}

func splitSelectors(s, sep string) []string {
	return strings.Split(s, sep)
}

func matchSingleSelector(root *xmlparse.Node, sel string) []*xmlparse.Node {
	// Split by combinators: space (descendant), ">" (child)
	tokens := tokenizeSelector(sel)
	// tokens is a sequence like: [{type:"sel",val:"body"},{type:"comb",val:">"},{type:"sel",val:"p"}]
	// Start with all elements matching the first simple selector as descendants of root.
	if len(tokens) == 0 {
		return nil
	}
	// Start: find all descendants matching tokens[0]
	var current []*xmlparse.Node
	collectAllElements(root, func(n *xmlparse.Node) {
		if simpleSelectorMatches(n, tokens[0].val) {
			current = append(current, n)
		}
	})
	i := 1
	for i < len(tokens) {
		comb := ">"
		if tokens[i].typ == "comb" {
			comb = tokens[i].val
			i++
		}
		if i >= len(tokens) {
			break
		}
		s := tokens[i].val
		i++
		var next []*xmlparse.Node
		if comb == ">" {
			for _, c := range current {
				for _, cc := range c.Children {
					if cc.Kind == xmlparse.NodeElement && simpleSelectorMatches(cc, s) {
						next = append(next, cc)
					}
				}
			}
		} else {
			// descendant
			for _, c := range current {
				collectAllElements(c, func(n *xmlparse.Node) {
					if n != c && simpleSelectorMatches(n, s) {
						next = append(next, n)
					}
				})
			}
		}
		current = next
	}
	return current
}

type cssToken struct {
	typ string // "sel" or "comb"
	val string
}

func tokenizeSelector(sel string) []cssToken {
	var toks []cssToken
	i := 0
	for i < len(sel) {
		// skip spaces
		if sel[i] == ' ' || sel[i] == '\t' {
			// Gather whitespace
			j := i
			for j < len(sel) && (sel[j] == ' ' || sel[j] == '\t') {
				j++
			}
			// If next char is > or + or ~, it's an explicit combinator. Otherwise descendant.
			if j < len(sel) && (sel[j] == '>' || sel[j] == '+' || sel[j] == '~') {
				c := string(sel[j])
				toks = append(toks, cssToken{typ: "comb", val: c})
				j++
				// skip more ws
				for j < len(sel) && (sel[j] == ' ' || sel[j] == '\t') {
					j++
				}
			} else if j < len(sel) {
				toks = append(toks, cssToken{typ: "comb", val: " "})
			}
			i = j
			continue
		}
		if sel[i] == '>' || sel[i] == '+' || sel[i] == '~' {
			toks = append(toks, cssToken{typ: "comb", val: string(sel[i])})
			i++
			for i < len(sel) && (sel[i] == ' ' || sel[i] == '\t') {
				i++
			}
			continue
		}
		// sel
		start := i
		for i < len(sel) && sel[i] != ' ' && sel[i] != '\t' && sel[i] != '>' && sel[i] != '+' && sel[i] != '~' {
			if sel[i] == '[' {
				// Skip to matching ]
				depth := 1
				i++
				for i < len(sel) && depth > 0 {
					if sel[i] == '[' {
						depth++
					}
					if sel[i] == ']' {
						depth--
					}
					i++
				}
				continue
			}
			i++
		}
		toks = append(toks, cssToken{typ: "sel", val: sel[start:i]})
	}
	return toks
}

func simpleSelectorMatches(n *xmlparse.Node, sel string) bool {
	if n.Kind != xmlparse.NodeElement {
		return false
	}
	// parse: optional tag, then .class #id [attr=val] sequences
	i := 0
	tag := ""
	if i < len(sel) && sel[i] != '.' && sel[i] != '#' && sel[i] != '[' {
		start := i
		for i < len(sel) && sel[i] != '.' && sel[i] != '#' && sel[i] != '[' {
			i++
		}
		tag = sel[start:i]
	}
	if tag != "" && tag != "*" && !strings.EqualFold(tag, n.Name) {
		return false
	}
	for i < len(sel) {
		c := sel[i]
		if c == '.' {
			i++
			start := i
			for i < len(sel) && sel[i] != '.' && sel[i] != '#' && sel[i] != '[' {
				i++
			}
			class := sel[start:i]
			// check class attribute
			cls := getAttr(n, "class")
			if !containsClass(cls, class) {
				return false
			}
		} else if c == '#' {
			i++
			start := i
			for i < len(sel) && sel[i] != '.' && sel[i] != '#' && sel[i] != '[' {
				i++
			}
			id := sel[start:i]
			if getAttr(n, "id") != id {
				return false
			}
		} else if c == '[' {
			i++
			start := i
			for i < len(sel) && sel[i] != ']' {
				i++
			}
			cond := sel[start:i]
			if i < len(sel) && sel[i] == ']' {
				i++
			}
			if !matchAttrCondition(n, cond) {
				return false
			}
		} else {
			break
		}
	}
	return true
}

func getAttr(n *xmlparse.Node, name string) string {
	for _, a := range n.Attrs {
		if a.Name == name {
			return a.Value
		}
	}
	return ""
}

func containsClass(classes, want string) bool {
	for _, c := range strings.Fields(classes) {
		if c == want {
			return true
		}
	}
	return false
}

func matchAttrCondition(n *xmlparse.Node, cond string) bool {
	eq := strings.Index(cond, "=")
	if eq < 0 {
		return getAttr(n, cond) != "" || attrExists(n, cond)
	}
	name := strings.TrimSpace(cond[:eq])
	val := strings.TrimSpace(cond[eq+1:])
	if len(val) >= 2 && (val[0] == '"' || val[0] == '\'') && val[len(val)-1] == val[0] {
		val = val[1 : len(val)-1]
	}
	return getAttr(n, name) == val
}

func attrExists(n *xmlparse.Node, name string) bool {
	for _, a := range n.Attrs {
		if a.Name == name {
			return true
		}
	}
	return false
}

func collectAllElements(n *xmlparse.Node, fn func(*xmlparse.Node)) {
	if n.Kind == xmlparse.NodeElement {
		fn(n)
	}
	for _, c := range n.Children {
		collectAllElements(c, fn)
	}
}
