package xmlparse

import (
	"bytes"
	"fmt"
	"strings"
)

// ParseHTML parses HTML-like content. Void elements become self-closing,
// and script/style content is treated as raw text.
func ParseHTML(data []byte) (*Node, error) {
	root := &Node{Kind: NodeDocument}
	stack := []*Node{root}
	pos := 0
	line := 1
	for pos < len(data) {
		parent := stack[len(stack)-1]
		// If we're inside <script> or <style>, read raw until matching close tag.
		if len(stack) > 1 {
			cur := stack[len(stack)-1]
			lcName := strings.ToLower(cur.Name)
			if lcName == "script" || lcName == "style" {
				// Find matching close tag
				closeTag := []byte("</" + cur.Name)
				idx := -1
				for i := pos; i < len(data); i++ {
					// match closeTag case-insensitively
					if i+len(closeTag) <= len(data) && caseInsensitivePrefix(data[i:], closeTag) {
						// Ensure followed by whitespace or '>'
						j := i + len(closeTag)
						for j < len(data) && (data[j] == ' ' || data[j] == '\t' || data[j] == '\n' || data[j] == '\r') {
							j++
						}
						if j < len(data) && data[j] == '>' {
							idx = i
							break
						}
					}
				}
				if idx < 0 {
					// End of input; treat rest as text.
					n := &Node{Kind: NodeText, Text: string(data[pos:]), Parent: parent}
					parent.Children = append(parent.Children, n)
					for _, b := range data[pos:] {
						if b == '\n' {
							line++
						}
					}
					pos = len(data)
					continue
				}
				text := string(data[pos:idx])
				n := &Node{Kind: NodeText, Text: text, Parent: parent}
				parent.Children = append(parent.Children, n)
				for _, b := range text {
					if b == '\n' {
						line++
					}
				}
				pos = idx
				// Now fall through to regular parsing to consume the end tag
			}
		}
		if data[pos] != '<' {
			// read text until next <
			start := pos
			for pos < len(data) && data[pos] != '<' {
				if data[pos] == '\n' {
					line++
				}
				pos++
			}
			text := string(data[start:pos])
			n := &Node{Kind: NodeText, Text: text, Parent: parent}
			parent.Children = append(parent.Children, n)
			continue
		}
		// Parse one token using tokenizer on the remaining data
		t := New(data[pos:])
		t.line = line
		tok, err := t.Next()
		if err != nil {
			return nil, err
		}
		if tok == nil {
			break
		}
		advance := len(tok.Raw)
		line = t.line
		switch tok.Kind {
		case TokenText:
			n := &Node{Kind: NodeText, Text: tok.Text, Parent: parent}
			parent.Children = append(parent.Children, n)
		case TokenComment:
			n := &Node{Kind: NodeComment, Text: tok.Text, Parent: parent}
			parent.Children = append(parent.Children, n)
		case TokenCData:
			n := &Node{Kind: NodeCData, Text: tok.Text, Parent: parent}
			parent.Children = append(parent.Children, n)
		case TokenDoctype:
			n := &Node{Kind: NodeDoctype, Text: tok.Text, Parent: parent}
			parent.Children = append(parent.Children, n)
		case TokenDecl:
			n := &Node{Kind: NodeDecl, Name: tok.Name, AttrsRaw: tok.Attrs, Parent: parent}
			n.Attrs = parseAttrsPairs(tok.Attrs)
			parent.Children = append(parent.Children, n)
		case TokenProcInst:
			n := &Node{Kind: NodeProcInst, PITarget: tok.Name, PIData: tok.Attrs, Parent: parent}
			parent.Children = append(parent.Children, n)
		case TokenSelfClose:
			n := &Node{Kind: NodeElement, Name: tok.Name, AttrsRaw: tok.Attrs, Parent: parent, SelfClose: true}
			n.Attrs = parseAttrsPairs(tok.Attrs)
			parent.Children = append(parent.Children, n)
		case TokenStart:
			n := &Node{Kind: NodeElement, Name: tok.Name, AttrsRaw: tok.Attrs, Parent: parent}
			n.Attrs = parseAttrsPairs(tok.Attrs)
			parent.Children = append(parent.Children, n)
			if isHTMLVoid(tok.Name) {
				n.SelfClose = true
			} else {
				stack = append(stack, n)
			}
		case TokenEnd:
			if len(stack) <= 1 {
				return nil, fmt.Errorf("XML syntax error on line %d: unexpected end element </%s>", line, tok.Name)
			}
			matchIdx := -1
			for i := len(stack) - 1; i > 0; i-- {
				if strings.EqualFold(stack[i].Name, tok.Name) {
					matchIdx = i
					break
				}
			}
			if matchIdx >= 0 {
				stack = stack[:matchIdx]
			}
		}
		pos += advance
	}
	return root, nil
}

func caseInsensitivePrefix(data, pat []byte) bool {
	if len(data) < len(pat) {
		return false
	}
	return bytes.EqualFold(data[:len(pat)], pat)
}

func isHTMLVoid(name string) bool {
	switch strings.ToLower(name) {
	case "area", "base", "br", "col", "embed", "hr", "img", "input",
		"link", "meta", "param", "source", "track", "wbr":
		return true
	}
	return false
}
